#!/usr/bin/env bash
# Generated by Agent Team Kit 0.17.0. Do not edit: fixes go upstream, settings go in .agent-team/config.sh.
# Shared helpers for the Agent Team Kit scripts. Sourced, never run.
#
# Sets:
#   AT_ROOT     the repository (or worktree) root
#   AT_PROJECT  a slug that is the same in every worktree of one repository
#   AT_ROLE     the role this checkout plays (AGENT_TEAM_ROLE), or empty
#   AT_HOME     per-project state outside the repo: $AGENT_TEAM_HOME/<project>, by default ~/.agent-team/<project>
#               (event log, team.env, locks)
# and sources, in this order: .agent-team/config.sh, gates.sh (from .agent-team/gates.json) next to this file,
# ~/.agent-team/<project>/team.env and .agent-team/local.env (gitignored, this checkout's own settings).
#
# AGENT_TEAM_HOME (where the event log lives, for example a folder every thread shares) and AGENT_TEAM_ROLE (the role
# this checkout plays) can be set in the environment, local.env, team.env or config.sh; the environment wins, then
# local.env, then team.env, then config.sh. When AGENT_TEAM_HOME moves the state folder, its own team.env is read too.

at_script_dir() { cd "$(dirname "${BASH_SOURCE[1]}")" && pwd; }

at_init() {
  AT_ROOT="${AGENT_TEAM_ROOT:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}"
  local config="${AGENT_TEAM_CONFIG:-$AT_ROOT/.agent-team/config.sh}"
  # Settings already in the environment win over the config file.
  local env_home="${AGENT_TEAM_HOME:-}" env_role="${AGENT_TEAM_ROLE:-}"
  local env_project="${AGENT_TEAM_PROJECT:-}" env_pools="${AGENT_TEAM_POOLS:-}" env_url="${TEAM_REPORT_URL:-}" env_mirror="${TEAM_REPORT_MIRROR_URL:-}"
  if [ -f "$config" ]; then
    # shellcheck disable=SC1090
    . "$config"
  fi
  # Gates from .agent-team/gates.json, generated next to this file by sync; they replace same-named gates in config.sh.
  local gates
  gates="$(dirname "${BASH_SOURCE[0]}")/gates.sh"
  if [ -f "$gates" ]; then
    # shellcheck disable=SC1090
    . "$gates"
  fi
  [ -n "$env_project" ] && AGENT_TEAM_PROJECT="$env_project"
  [ -n "$env_pools" ] && AGENT_TEAM_POOLS="$env_pools"
  [ -n "$env_url" ] && TEAM_REPORT_URL="$env_url"
  [ -n "$env_mirror" ] && TEAM_REPORT_MIRROR_URL="$env_mirror"
  if [ -z "${AGENT_TEAM_PROJECT:-}" ]; then
    local common
    common="$(git -C "$AT_ROOT" rev-parse --git-common-dir 2>/dev/null || true)"
    case "$common" in ""|/*) ;; *) common="$AT_ROOT/$common" ;; esac
    if [ -n "$common" ]; then AGENT_TEAM_PROJECT="$(basename "$(dirname "$common")")"; else AGENT_TEAM_PROJECT="$(basename "$AT_ROOT")"; fi
  fi
  AT_PROJECT="$(printf '%s' "$AGENT_TEAM_PROJECT" | tr '[:upper:]' '[:lower:]' | tr -cs 'a-z0-9_-' '-' | sed 's/^-*//; s/-*$//')"
  # team.env (secrets and machine settings) and local.env (this checkout's role and board) may set AGENT_TEAM_HOME and
  # AGENT_TEAM_ROLE; the environment still wins for those two.
  local base="${env_home:-${AGENT_TEAM_HOME:-$HOME/.agent-team}}" f
  for f in "$base/$AT_PROJECT/team.env" "$AT_ROOT/.agent-team/local.env"; do
    if [ -f "$f" ]; then
      set -a
      # shellcheck disable=SC1090
      . "$f"
      set +a
    fi
  done
  [ -n "$env_home" ] && AGENT_TEAM_HOME="$env_home"
  [ -n "$env_role" ] && AGENT_TEAM_ROLE="$env_role"
  AT_HOME="${AGENT_TEAM_HOME:-$HOME/.agent-team}/$AT_PROJECT"
  # A state folder set in team.env or local.env can hold its own team.env (a shared board's URL and token).
  if [ "$AT_HOME" != "$base/$AT_PROJECT" ] && [ -f "$AT_HOME/team.env" ]; then
    # shellcheck disable=SC1091
    set -a; . "$AT_HOME/team.env"; set +a
    [ -n "$env_home" ] && AGENT_TEAM_HOME="$env_home"
    [ -n "$env_role" ] && AGENT_TEAM_ROLE="$env_role"
  fi
  AT_HOME="${AGENT_TEAM_HOME:-$HOME/.agent-team}/$AT_PROJECT"
  AT_ROLE="${AGENT_TEAM_ROLE:-}"
  export AT_ROOT AT_PROJECT AT_HOME AT_ROLE
}

# Aligns tab-separated lines into columns (no dependency on column(1), which some systems lack).
at_align() {
  awk -F'\t' '{ rows[NR] = $0; for (i = 1; i <= NF; i++) if (length($i) > w[i]) w[i] = length($i); if (NF > n) n = NF }
    END { for (r = 1; r <= NR; r++) { k = split(rows[r], f, "\t"); line = "";
      for (i = 1; i <= k; i++) line = line (i < k ? sprintf("%-" w[i] + 2 "s", f[i]) : f[i]); sub(/ +$/, "", line); print line } }'
}
